using namespace std;

int main() {
    int q;
    scanf("%d", &q);
    string out = to_string(q) + "\n";
    for (int i = 0; i < q; i++) {
        long long n, m, s, u;
        scanf("%lld %lld %lld %lld", &n, &m, &s, &u);
        // Upgrading x needs x*u <= m + (n - x)*s, i.e. x*(u + s) <= m + n*s.
        if (i) out += ' ';
        out += to_string(min(n, (m + n * s) / (u + s)));
    }
    puts(out.c_str());
}

import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int q = nextInt();
        StringBuilder sb = new StringBuilder();
        sb.append(q).append('\n');
        for (int i = 0; i < q; i++) {
            long n = nextLong(), m = nextLong(), s = nextLong(), u = nextLong();
            // Upgrading x needs x*u <= m + (n - x)*s, i.e. x*(u + s) <= m + n*s.
            if (i > 0) sb.append(' ');
            sb.append(Math.min(n, (m + n * s) / (u + s)));
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	q := int(nextInt())
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteString(strconv.Itoa(q) + "\n")
	for i := 0; i < q; i++ {
		n, m, s, u := nextInt(), nextInt(), nextInt(), nextInt()
		// Upgrading x needs x*u <= m + (n - x)*s, i.e. x*(u + s) <= m + n*s.
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.FormatInt(min(n, (m+n*s)/(u+s)), 10))
	}
	w.WriteByte('\n')
}
